const ic=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icoPaths[name]||icoPaths.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(r,label,cls='btn')=>`<a class="${cls}" href="#${r}">${label}</a>`;
const btn=(label,action,cl='btn',extra='')=>`<button type="button" class="${cl}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(text,type='blue')=>`<span class="pill ${type}">${text}</span>`;
const card=(title,body,action='')=>`<section class="card"><div class="card-title"><h2>${title}</h2>${action}</div>${body}</section>`;
const panel=(title,caption,body)=>`<div class="page-head"><div><div class="eyebrow">${caption}</div><h1>${title}</h1></div></div>${body}`;
