try{const saved=JSON.parse(localStorage.getItem('xuliu_demo_v1')||'null');if(saved&&typeof saved==='object')state={...DEFAULT,...saved};}catch(e){}
const persist=()=>{try{localStorage.setItem('xuliu_demo_v1',JSON.stringify(state))}catch(e){}};
const set=(patch,rerender=true)=>{state={...state,...patch};persist();if(rerender)render()};
const route=()=>{let r=decodeURI(location.hash.slice(1)||'/dashboard');return PAGE_LIST.some(x=>x[0]===r)?r:'/dashboard'};
function toast(text){const root=document.getElementById('toast-stack');const n=document.createElement('div');n.className='toast';n.textContent=text;root.appendChild(n);setTimeout(()=>n.remove(),4300)}
function goto(r){location.hash=r;if(route()===r)render();document.querySelector('.sidebar')?.classList.remove('open');window.scrollTo({top:0})}
function head(title,sub,actions='',eyebrow='WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow} &nbsp;·&nbsp; ${simB()}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function metricsCard(name,num,description,iconName='chart'){return `<div class="card metric"><div class="space-between"><span class="m-label">${name}</span>${ic(iconName,18)}</div><div class="m-value">${num}</div><div class="m-caption">${description}</div></div>`}
function niceDate(n){return `11月${n}日`}
function poster(cls=''){return `<div class="poster ${cls}"><div class="fake-ui"></div><div class="poster-title">${cls==='mint'?'面试回答\n这样练习':cls==='alt'?'项目追问\n怎么准备':'让每一次练习\n更有方向'}</div><div class="poster-foot">有招 · PRODUCT STORY</div></div>`}
function renderSidebar(){const r=route();document.getElementById('sidebar').innerHTML=`<a href="#/dashboard" class="brandbar"><div class="brandmark">叙</div><div class="brandtext"><strong>叙流 XULIU</strong><div class="tiny">AI Creator Studio</div></div></a><button class="workspace-btn" data-action="workspace"><div class="workspace-symbol">有</div><div class="flex"><div class="bold small">有招工作区</div><div class="tiny">软件品牌创作</div></div><span class="chevron">${ic('down',13)}</span></button>${HEAD_NAV.map(g=>`<div class="sidebar-group">${g.g}</div>${g.items.map(x=>`<a title="${x[1]}" href="#${x[0]}" class="nav-item ${r===x[0]||(x[0]!=='/dashboard'&&r.startsWith(x[0]+'/'))?'active':''}">${ic(x[2])}<span>${x[1]}</span>${x[0]==='/publish'&&state.drafts.filter(d=>d.status==='待人工发布').length?`<b class="nav-dot">${state.drafts.filter(d=>d.status==='待人工发布').length}</b>`:''}</a>`).join('')}`).join('')}<div class="sidebar-foot"><a href="#/help" class="nav-item">${ic('help')}<span>帮助与反馈</span></a><div class="notice">AI 每日创作 · 平台发布由用户本人完成。原型内所有内容为示例。</div></div>`;
const mitems=[['/dashboard','dashboard','总览'],['/calendar','calendar','日历'],['/campaigns','layers','作品'],['/publish','send','发布'],['/settings','settings','我的']];document.getElementById('mobile-tabs').innerHTML=mitems.map(x=>`<a class="${r===x[0]||r.startsWith(x[0]+'/')?'active':''}" href="#${x[0]}">${ic(x[1])}<span>${x[2]}</span></a>`).join('')}
function renderTopbar(){let r=route(),title=PAGE_LIST.find(x=>x[0]===r)?.[1]||'创作者工作台';document.getElementById('topbar').innerHTML=`<div class="top-left"><button class="top-icon mobile-menu" data-action="menu" aria-label="打开导航">${ic('menu',19)}</button><span class="crumb">有招工作区 &nbsp;/&nbsp; <strong>${esc(title)}</strong></span></div><div class="top-right"><button class="top-search" data-action="search">${ic('search',14)} 搜索页面和功能 <span style="margin-left:auto">⌘ K</span></button><button class="top-icon" data-action="theme" title="切换主题">${ic(state.theme==='dark'?'sun':'moon',18)}</button><button class="top-icon" data-action="notifications" title="通知">${ic('bell',18)}</button><button class="top-icon" data-action="help" title="使用手册">${ic('help',18)}</button><button class="avatar" data-action="settings">创</button></div>`}
function dashboard(){const ready=state.drafts.filter(x=>x.status==='待人工发布').length;return head('早上好，今天继续创作。',`“${esc(state.creatorName)}”正在按计划为你的软件准备内容。`,`${link('/creator',ic('bot')+' 管理创作者')}`, 'TODAY OVERVIEW')+`<section class="section"><div class="hero"><div style="max-width:65%"><div class="pill green" style="border-color:#6dcea663;color:#96eccb;margin-bottom:14px">${ic(state.paused?'pause':'spark',12)} ${state.paused?'创作已暂停':'持续创作模式已开启'}</div><h2>让你的软件，每天都有值得被看到的故事。</h2><p>AI 制定选题、生成图文与多类型宣传视频，你在平台官方界面自行发布。反馈数据会成为下一次创作的依据。</p><div class="flex-row">${link('/calendar','查看本周计划 '+ic('arrow',13),'btn primary')}${link('/publish','今日待手动发布','btn')}</div></div><div class="hero-stat"><div class="mini-window"><div class="window-dots"><i></i><i></i><i></i></div><div class="bar long"></div><div class="bar med"></div><div class="bar short"></div></div><div class="spark"></div></div></div></section><div class="g4 section">${metricsCard('今日内容任务','2','演示：1 条混合视频 · 1 篇图文','calendar')}${metricsCard('待用户手动发布',String(ready),'仅准备资料，不代替你发帖','send')}${metricsCard('已登记发布',String(state.published.length),'用户自行登记，非平台验证','check')}${metricsCard('本月创作预算',`¥${state.budget}`,'示例设定，不计真实费用','chart')}</div><div class="split section">${card('今日 AI 创作流程',`<div class="space-between" style="margin-bottom:14px"><span class="small muted">基于你锁定的品牌事实和内容栏目</span>${pill(state.paused?'已暂停':'按计划运行',state.paused?'gold':'green')}</div><div class="status-stages"><span class="stage done"></span><span class="stage done"></span><span class="stage done"></span><span class="stage current"></span><span class="stage"></span></div><div style="margin-top:18px" class="timeline">${[['已完成选题分析','08:15 · 使用历史选题和品牌资料'],['AI 内容制作','09:20 · 示意：图文及 宣传片'],['合规预审','09:48 · 仍需用户核实'],['等待手动发布','现在 · 请在官方客户端自行操作']].map((e,i)=>`<div class="event"><span class="marker">${ic(i===3?'clock':'check',12)}</span><div><strong>${e[0]}</strong><div class="meta">${e[1]}</div></div></div>`).join('')}</div>`,link('/creator/activity','运行日志','action-link'))}${card('今天需要你处理',`<div class="stack">${state.drafts.filter(d=>d.status==='待人工发布').slice(0,2).map(d=>`<div class="item-row"><div class="iconbox">${ic(d.type==='宣传视频'?'video':'file')}</div><div class="item-info"><strong>${esc(d.type)}资料已准备</strong><div class="sub">${esc(d.title)}</div></div>${link('/publish/package/1',ic('arrow',14),'btn small')}</div>`).join('')}<div class="panel-note"><strong>账号保护：</strong>系统不会登录或操作你的社媒账号，所有公开发布由你本人完成。</div></div>`,link('/publish','前往人工发布中心','action-link'))}</div><div class="split section">${card('最新作品',`<div class="g3">${['','alt','mint'].map((x,i)=>`<a href="#${i===0?'/studio/video/1':'/studio/article/1'}" style="display:block">${poster(x)}<div style="font-size:12px;margin-top:9px;font-weight:700">${['30 秒软件 宣传片','面试项目介绍技巧','复盘清单图文'][i]}</div><div class="smaller muted">${['待手动发布','待手动发布','待审核'][i]}</div></a>`).join('')}</div>`,link('/campaigns','进入内容库','action-link'))}${card('本周成长与洞察',`<div class="learning-highlight"><div class="flex-row" style="color:var(--teal)">${ic('spark')}<strong>持续学习已启用</strong></div><p>AI 会根据真实作品数据和用户反馈提出新选题，重大策略变化由你批准。</p></div><div class="divider"></div><div class="empty" style="padding:28px 10px">${ic('chart')}<strong>还没有导入运营指标</strong><div class="small">先完成手动发布，再导入官方报表或手工指标。</div>${link('/analytics/import','导入数据','btn small')}</div>`,link('/growth','查看成长报告','action-link'))}</div>`}
function creator(){return head('我的 AI 创作者','它拥有稳定的人设与栏目，会长期累积真正的创作经验。',`${btn(state.paused?'恢复创作':'暂停创作',state.paused?'resume':'pause',state.paused?'btn primary':'btn danger')}${link('/creator/edit',ic('sliders')+' 编辑设定')}`,'CREATOR IDENTITY')+`<div class="split section"><div class="card"><div class="flex-row" style="align-items:flex-start;gap:18px"><div class="brandmark" style="height:70px;width:70px;font-size:32px">有</div><div class="flex"><div class="space-between"><div><h2 style="margin:0;font-size:21px">${esc(state.creatorName)}</h2><div class="muted small" style="margin-top:3px">${esc(state.brand)}</div></div>${pill(state.paused?'暂停中':'持续运行',state.paused?'gold':'green')}</div><div class="tags" style="margin-top:14px"><span class="tag">软件品牌创作</span><span class="tag">多风格宣传视频</span><span class="tag">客观功能讲解</span><span class="tag">人工发布</span></div></div></div><div class="divider"></div><div class="g3"><div><div class="tiny">更新频率</div><div class="bold">${esc(state.frequency)}</div></div><div><div class="tiny">时区</div><div class="bold">${esc(state.timezone)}</div></div><div><div class="tiny">单月预算</div><div class="bold">¥${state.budget}</div></div></div><div class="divider"></div><div class="panel-note"><strong>创作身份：</strong>分享面试练习、软件真实功能和使用方法。不得冒充真实用户或虚构体验评价。</div></div>${card('最近运行事件',`<div class="timeline">${[['内容已进入人工发布待办','示例数据 · 今天'],['创作者更新了下周选题候选','示例数据 · 昨天'],['品牌资料检查通过','示例数据 · 前天']].map(x=>`<div class="event"><span class="marker">${ic('check',12)}</span><div><strong>${x[0]}</strong><div class="meta">${x[1]}</div></div></div>`).join('')}</div>`,link('/creator/activity','全部日志','action-link'))}</div><div class="g3">${card('创作栏目',`<div class="stack"><div class="space-between"><span>使用教程</span>${pill('35%')}</div><div class="progress-line"><span style="width:35%"></span></div><div class="space-between"><span>软件 CG 展示</span>${pill('30%')}</div><div class="progress-line"><span style="width:30%"></span></div><div class="space-between"><span>面试知识</span>${pill('35%')}</div><div class="progress-line"><span style="width:35%"></span></div></div>`)}${card('运营目标',`<h3 style="margin:2px 0 9px">获取准确的软件需求与咨询</h3><div class="muted small">不盲目追逐曝光量，以真实内容理解和有效咨询为主要目标。</div><div style="margin-top:21px">${link('/growth','查看策略及依据','btn small')}</div>`)}${card('人工发布原则',`<div class="flex-row" style="color:var(--teal)">${ic('shield')} <strong>已固定</strong></div><p class="small muted">AI 每天自动生产作品和发布包；平台上传、点击公开发布、AI 内容声明均由你本人完成。</p><div style="margin-top:17px">${link('/publish','打开待发布中心','btn small')}</div>`)}</div>`}
function creatorEdit(){return head('创作者设置','对长期设定的修改将影响未来计划，不自动修改已经生成或发布的作品。',`${btn('保存创作者设置','save-creator','btn primary')}${link('/creator','取消')}`,'CREATOR SETTINGS')+`<div class="split"><div class="stack-lg">${card('基础资料',`<div class="form-grid"><div class="field"><label for="creator-name">创作者名称</label><input id="creator-name" value="${esc(state.creatorName)}"></div><div class="field"><label for="creator-frequency">更新频率</label><select id="creator-frequency"><option ${state.frequency==='每天 1 条'?'selected':''}>每天 1 条</option><option ${state.frequency==='每周 5 条'?'selected':''}>每周 5 条</option><option ${state.frequency==='每周 3 条'?'selected':''}>每周 3 条</option></select></div><div class="field"><label for="creator-timezone">日程时区</label><select id="creator-timezone"><option ${state.timezone==='Asia/Shanghai'?'selected':''}>Asia/Shanghai</option><option ${state.timezone==='Asia/Tokyo'?'selected':''}>Asia/Tokyo</option></select></div><div class="field"><label for="creator-budget">月预算上限（人民币）</label><input id="creator-budget" type="number" min="0" max="20000" value="${state.budget}"></div></div>`)}${card('创作定位和限制',`<div class="field"><label>目标受众</label><textarea id="creator-target">${esc(state.target)}</textarea></div><div class="panel-note" style="margin-top:13px"><strong>不可关闭：</strong>使用真实产品界面、拒绝虚构数据、视频标识需人工确认、第三方账号只允许手动发布。</div>`)}</div>${card('变更预览',`<div class="stack"><div class="item-row"><div class="item-info"><strong>下一次日更</strong><div class="sub">按新频率和所选时区计算；原型不连接实际调度器</div></div>${pill('示例','gold')}</div><div class="item-row"><div class="item-info"><strong>历史内容和学习记录</strong><div class="sub">保持不变，采用版本化管理</div></div>${pill('保留','green')}</div><div class="item-row"><div class="item-info"><strong>社媒账号权限</strong><div class="sub">无需输入账号密码或 Cookie</div></div>${pill('不采集','green')}</div></div><div class="divider"></div>${btn(state.paused?'恢复创作者':'暂停创作者',state.paused?'resume':'pause','btn danger')}`)}</div>`}
function activity(){return head('创作者运行日志','所有运行状态都需可追溯；这是用于检查信息结构的示例记录。',`${link('/creator','返回创作者')}`,'EXECUTION HISTORY')+card('近七日执行活动',`<div class="table-wrap"><table class="table"><thead><tr><th>日期</th><th>任务</th><th>执行阶段</th><th>结果</th><th>说明</th></tr></thead><tbody>${[5,4,3,2,1].map((d,i)=>`<tr><td>2026-11-${String(d).padStart(2,'0')}</td><td>日更 · 软件内容</td><td>${['发布包已准备','等待内容复核','已生成候选','已记录选题','已生成草稿'][i]}</td><td>${pill(i===0?'等待用户':'示例任务',i===0?'gold':'blue')}</td><td>演示过程，未执行真实后台任务</td></tr>`).join('')}</tbody></table></div><div class="panel-note" style="margin-top:16px">正式产品应记录每一步的任务 ID、幂等键、模型成本、来源和异常信息。原型不会自动触发真实日更。</div>`)}
function calendar(){let days=Array.from({length:35},(_,i)=>i-5);return head('运营内容日历','按栏目长期规划内容。这里的“排期”是创作/人工提醒时间，不是平台自动发帖时间。',`${btn(ic('plus')+' 新增选题','add-topic','btn primary')}${link('/topics','查看选题池')}`,'EDITORIAL CALENDAR')+`<div class="split section"><div class="card"><div class="space-between" style="margin-bottom:15px"><div><strong style="font-size:17px">2026 年 11 月</strong><div class="tiny">计划示例 · 周日起始</div></div><div class="tabs"><button class="tab active">月视图</button><button class="tab" data-action="calendar-week">周视图</button></div></div><div class="calendar-grid">${['日','一','二','三','四','五','六'].map(d=>`<div class="weekday">${d}</div>`).join('')}${days.map(d=>{let n=d>0&&d<=30?d:null;let txt=n?(['项目追问图文','MG 动态图形','技巧干货','功能演示','教程回顾','经验总结','选题复盘'][(n+2)%7]):'';return `<button class="day-cell ${n===state.selectedDay?'selected':''} ${!n?'dim':''}" data-action="select-day" data-day="${n||0}" ${!n?'disabled':''}><div class="day-num">${n||''} ${n===5?'<span style="color:var(--primary)">· 今日</span>':''}</div>${n&&n>=5&&n<19?`<div class="day-content ${n%3===0?'video':'article'}">${n%3===0?'▶':'▤'} ${txt}</div>`:''}</button>`}).join('')}</div></div>${card(`${niceDate(state.selectedDay)} · 创作安排`,`<div class="stack"><div class="panel-note">当天的选题与发布包仅为原型演示。实际时间与执行状态需要后台调度。</div>${[0,1].map((i)=>`<div class="item-row"><div class="iconbox">${ic(i?'image':'video')}</div><div class="item-info"><strong>${i?'面试技巧图文':'混合宣传视频'}</strong><div class="sub">${i?'12:00 · 计划创作':'09:00 · 计划创作'}</div></div>${pill(i?'草稿':'待手动发布',i?'blue':'gold')}</div>`).join('')}<div class="divider"></div>${link('/campaigns','查看全部作品','btn')}${link('/creator/edit','调整更新频率','btn')}</div>`)}</div>`}
function topics(){const tabs=['全部','图文','宣传视频'];let tt=EXAMPLE.topics.filter(t=>state.contentTab==='全部'||state.contentTab===t.kind);return head('选题池','AI 根据品牌定位、栏目计划和真实反馈提出内容方向，不是每天随机生成一条广告。',`${btn(ic('spark')+' 生成候选选题','generate-topics','btn primary')}`,'TOPIC LIBRARY')+`<div class="space-between section"><div class="tabs">${tabs.map(t=>`<button class="tab ${state.contentTab===t?'active':''}" data-action="tab" data-value="${t}">${t}</button>`).join('')}</div>${pill('评分仅为示意 · 非平台推荐算法')}</div><div class="g3">${tt.map((t,i)=>`<div class="card"><div class="space-between"><span class="tag">${esc(t.category)}</span>${pill(t.kind,t.kind==='宣传视频'?'blue':'green')}</div><h3 style="font-size:16px;margin:18px 0 8px;line-height:1.5">${esc(t.title)}</h3><p class="small muted" style="min-height:55px">匹配真实功能与用户使用场景。下一步需要查看参考事实和重复内容。</p><div class="divider"></div><div class="space-between"><span class="small muted">候选优先级 ${t.score} · 示例</span>${link('/topics/1','查看选题 '+ic('arrow',13),'action-link')}</div></div>`).join('')}</div>`}
function topicDetail(){return head('选题分析与内容假设','每个长期选题都应说明来源、目标和证据，而不是只有一个标题。',`${link('/topics','返回选题池')}${btn('采用这个选题','adopt-topic','btn primary')}`,'TOPIC RESEARCH')+`<div class="split">${card('30 秒看懂 AI 面试练习软件',`<div class="tags"><span class="tag">软件 CG</span><span class="tag">功能演示</span><span class="tag">非真人内容</span></div><h3>核心表达</h3><p class="muted">用真实界面和 2.5D 卡片动画演示软件如何辅助面试练习，突出操作路径而不是夸大效果。</p><h3>内容假设</h3><p class="muted">相比直接宣传功能列表，具体展示工作过程可能更容易让目标用户理解产品。尚无数据支持，需要后续验证。</p><h3>可用证据</h3><div class="checklist">${EXAMPLE.features.map(x=>`<div class="checkline">${ic('check',14)} ${x}（上线前需核实真实版本）</div>`).join('')}</div>`)}${card('创作计划',`<div class="field"><label>目标内容形式</label><select><option>CG 软件宣传片 · 30 秒</option><option>小红书图文</option></select></div><div class="field" style="margin-top:13px"><label>计划平台版本</label><select><option>抖音竖屏 9:16</option><option>小红书图文封面</option></select></div><div class="panel-note" style="margin-top:16px">AI 不会根据“采用选题”直接对外发帖。后续仍需用户完成官方发布。</div>${link('/studio/video/new',ic('video')+' 进入 CG 工作室','btn primary')}`)}</div>`}
function campaigns(){let list=state.drafts.filter(d=>state.contentTab==='全部'||d.status===state.contentTab);return head('内容作品库','统一管理每日图文、宣传视频、审查记录和人工发布登记。',`${link('/studio/video/new',ic('plus')+' 创作 宣传视频','btn primary')}${link('/studio/article/1','打开图文编辑器')}`,'CONTENT LIBRARY')+`<div class="section flex-row" style="flex-wrap:wrap">${['全部','待人工发布','待审核','已登记'].map(t=>`<button class="btn small ${state.contentTab===t?'primary':''}" data-action="tab" data-value="${t}">${t}</button>`).join('')}</div><div class="g3">${list.map((d,i)=>`<div class="card" style="padding:10px"><a href="#${d.type==='宣传视频'?'/studio/video/1':'/studio/article/1'}">${poster(i%3===0?'':i%3===1?'alt':'mint')}</a><div style="padding:7px 4px 5px"><div class="space-between" style="margin-bottom:8px">${pill(d.type==='宣传视频'?'宣传视频':'图文','blue')}${pill(d.status,d.status==='待人工发布'?'gold':'blue')}</div><strong style="font-size:13px">${esc(d.title)}</strong><div class="smaller muted" style="margin:7px 0 10px">${esc(d.platform)} · ${esc(d.date)}</div><div class="flex-row">${link(d.type==='宣传视频'?'/studio/video/1':'/studio/article/1','继续编辑','btn small')}${link('/publish/package/1','发布资料','btn small')}</div></div></div>`).join('')}</div>`}
function article(){return head('图文内容编辑器','支持真实素材、平台尺寸适配、文案编辑及版本化审核。',`${btn('保存文案草稿','save-copy','btn')}${link('/compliance/1','查看合规检查','btn primary')}`,'ARTICLE STUDIO')+`<div class="content-pair"><div class="card"><div class="card-title"><h2>封面预览</h2>${link('/studio/covers','更换封面模板','action-link')}</div><div style="max-width:365px;margin:auto">${poster('mint')}</div><div class="panel-note" style="margin-top:18px">此为 CSS 演示预览，并非 AI 已制作好的图片。正式版将使用真实素材输出封面文件。</div></div>${card('文案与平台版本',`<div class="field"><label for="copy-title">笔记标题</label><input id="copy-title" value="${esc(state.editedTitle)}"></div><div class="field" style="margin-top:15px"><label for="copy-body">内容正文</label><textarea id="copy-body" style="min-height:235px">${esc(state.editedCopy)}</textarea></div><div class="field" style="margin-top:15px"><label>目标平台格式</label><select><option>小红书图文</option><option>抖音图文</option></select></div><div class="divider"></div><div class="panel-note warning-note">修改文案后，之前的合规预审结论应失效，需要重新检测。</div>${btn('重新检查文案','check-article','btn primary')}`)}</div>`}
function covers(){return head('封面与动效模板','从简约品牌卡片到科技感视觉排版，保持每日作品的一致风格和适度变化。',`${link('/studio/article/1','应用到图文','btn primary')}`,'COVER SYSTEM')+`<div class="g3">${['','mint','alt','','alt','mint'].map((c,i)=>`<div class="card" style="padding:10px">${poster(c)}<div class="space-between" style="padding:8px 4px 4px"><strong class="small">${['深蓝科技','薄荷效率','微光产品','清透几何','功能聚焦','教程卡片'][i]}</strong>${btn('使用','use-cover','btn small')}</div><div class="smaller muted" style="padding:0 4px 5px">模板结构 · 不是已渲染图片</div></div>`).join('')}</div>`}
function assets(){return head('品牌素材库','软件截图、实际录屏、Logo、字体与音效许可，是可信宣传片的基础。',`${btn(ic('upload')+' 添加素材','add-asset','btn primary')}`,'ASSET LIBRARY')+`<div class="g4">${[['真实主界面截图','image','来源：演示占位'],['Logo 与品牌配色','spark','品牌资产需确认'],['功能操作录屏','video','等待用户上传'],['授权音效素材','box','需记录商业授权']].map((x,i)=>`<div class="card"><div style="height:120px;background:var(--surface2);border-radius:11px;display:grid;place-items:center;color:var(--primary)">${ic(x[1],38)}</div><h3 style="font-size:13px;margin:15px 0 5px">${x[0]}</h3><div class="small muted">${x[2]}</div><div style="margin-top:15px">${pill(i<2?'待补充来源':'未添加',i<2?'gold':'blue')}</div></div>`).join('')}</div><div class="panel-note" style="margin-top:20px">只有来源可靠且获授权的软件截图、真实录屏，才能用于标记“真实界面演示”的宣传片。当前原型没有上传或采集用户文件。</div>`}
function videoNew(){
 const modes=`<div class="video-modes">${VIDEO_MODES.map((m,i)=>`<button class="mode-choice ${state.videoMode===m.id?'active':''}" data-action="video-mode" data-mode="${m.id}" title="${m.sub}"><span class="mode-glyph">${['✦','◈','⬡','☷','▣','✧','▤','▦'][i]}</span><strong>${m.title}</strong><small>${m.sub}</small></button>`).join('')}</div>`;
 return head('新建 AI 宣传视频','支持 MG、3D/CG、卡通、软件录屏、AI 创意、素材混剪及多风格混合制作。',`${link('/studio/video/1','打开示例编辑器','btn primary')}`,'AI PROMO VIDEO STUDIO')+
 `<div class="split section"><div class="stack-lg">
 ${card('第一步 · 宣传目标与素材',`<div class="form-grid"><div class="field"><label>视频目标</label><select id="promo-goal"><option>讲清软件功能</option><option>提高品牌认知</option><option>讲解使用教程</option><option>引导查看产品详情</option></select></div><div class="field"><label>核心受众</label><input value="求职与面试练习用户" disabled title="演示原型从品牌设定读取"></div></div><div class="panel-note" style="margin-top:13px">可使用真实截图/录屏、授权图片、视频素材、Logo 和图生视频参考图。真实产品功能镜头必须有可靠证据，创意动画可使用合法授权素材。</div>${link('/studio/assets','查看素材库','btn small')}`)}
 ${card('第二步 · 选择宣传视频类型',`${modes}<div class="panel-note" style="margin-top:14px">${VIDEO_MODES.find(m=>m.id===state.videoMode).title}：${VIDEO_MODES.find(m=>m.id===state.videoMode).sub}。正式版由 Agent 生成不同方案，可逐镜头切换制作引擎。</div>`)}
 ${card('第三步 · 视频参数',`<div class="form-grid"><div class="field"><label>时长</label><select id="video-duration">${['15','30','60'].map(x=>`<option value="${x}" ${state.duration===x?'selected':''}>${x} 秒</option>`).join('')}</select></div><div class="field"><label>画面比例</label><select id="video-ratio">${['9:16','16:9','1:1'].map(x=>`<option ${state.ratio===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>成本策略</label><select><option>质量优先但不超预算</option><option>优先低成本素材</option><option>创意优先（需批准费用）</option></select></div><div class="field"><label>配音方式</label><select><option>AI 配音</option><option>无配音，仅文字音乐</option><option>上传授权录音</option></select></div></div>`)}
 ${btn(ic('spark')+' 生成混合分镜示例','create-video','btn primary')}
 </div>
 ${card('不同视频模式 · 预览',`<div class="stage-preview" style="min-height:310px"><div class="cg-card"><div class="cg-head">有招 AI · CREATOR STUDIO</div><div class="cg-row"><div class="cg-small"></div><div class="cg-lines"><i></i><i></i><i></i></div></div></div><div class="cg-flare"></div></div><div class="divider"></div><div class="bold small">${VIDEO_MODES.find(m=>m.id===state.videoMode).title}</div><p class="small muted">这是离线交互原型的视觉示意，不会调用生成模型、编排引擎，也不会产生 MP4。</p>${link('/studio/video/1/storyboard','查看多类型分镜','btn')}`)}
 </div>`;
}
function renderStage(){return `<div class="stage-preview ${state.playing?'stage-playing':''}"><div style="position:absolute;top:17px;left:18px;color:#8badde;font-size:10px;letter-spacing:1.2px">SCENE ${String(state.selectedShot+1).padStart(2,'0')} · PREVIEW</div><div class="cg-card"><div class="cg-head">有招 · AI 面试智能体</div><div class="cg-row"><div class="cg-small"></div><div class="cg-lines"><i></i><i></i><i></i></div></div><div class="cg-row"><div class="cg-small" style="background:#3d647c"></div><div class="cg-lines"><i style="width:80%"></i><i style="width:60%"></i></div></div></div><div class="cg-flare"></div><div style="position:absolute;bottom:14px;left:18px;color:#9fb3d1;font-size:10px">PROMO VIDEO · 静态编辑预览（非真实成片）</div></div>`}
function videoEditor(){
 const engine=state.shotEngines?.[state.selectedShot]||'openfilm';
 return head('AI 宣传视频 · 多引擎编辑工作台',`${state.duration} 秒 · ${state.ratio} · 整片模式：${VIDEO_MODES.find(x=>x.id===state.videoMode)?.title||'AI 智能推荐'} · 示例工程`,`${btn(state.playing?ic('pause')+' 暂停预览':ic('play')+' 播放预览','toggle-play','btn')}${link('/studio/video/1/render',ic('video')+' 渲染流程','btn primary')}`,'MULTI-ENGINE VIDEO EDITOR')+
 `<div class="shot-layout section">
 <div class="shot-sidebar"><div class="card-title" style="margin-bottom:10px"><h3>镜头 / 制作类型</h3>${link('/studio/video/1/storyboard',ic('more',15),'action-link')}</div>${EXAMPLE.shots.map((x,i)=>`<button class="shot ${state.selectedShot===i?'selected':''}" data-action="shot" data-shot="${i}"><span class="shot-index">0${i+1}</span><span style="text-align:left"><strong class="small">${x[0]}</strong><small>${x[1]}</small><small>${SHOT_ENGINES.find(y=>y[0]===(state.shotEngines?.[i]||'openfilm'))?.[1]||'未设置'}</small></span></button>`).join('')}</div>
 <div class="stage-wrap">${renderStage()}<div class="stage-controls"><button class="btn small" data-action="toggle-play">${ic(state.playing?'pause':'play',14)} ${state.playing?'暂停':'预览'}</button><span class="tiny">镜头 ${state.selectedShot+1}/${EXAMPLE.shots.length} · HTML 视觉示意</span><span class="tiny">${state.duration}.0s</span></div>
 <div style="margin-top:17px">${[['画面镜头',1],['动效/图层',2],['字幕',3],['音效/配音',4]].map(([label,n])=>`<div class="track"><div class="track-label">${label}</div><div class="trackbar">${EXAMPLE.shots.slice(0,n===4?3:6).map(()=>`<div class="clip ${n===2?'green':n===4?'purple':''}"></div>`).join('')}</div></div>`).join('')}</div></div>
 <div class="shot-inspector"><div class="card-title"><h3>镜头引擎</h3>${pill(`0${state.selectedShot+1}`)}</div><strong class="small">${EXAMPLE.shots[state.selectedShot][0]}</strong>
 <div class="inspector-input"><label>制作工具（每个镜头独立）</label><select id="shot-engine">${SHOT_ENGINES.map(x=>`<option value="${x[0]}" ${engine===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div>
 <div class="inspector-input"><label>本镜头的技术说明</label><div class="panel-note">${engine==='comfy_wan'?'生成式素材需核对模型权重许可、AI 标识和预算。':engine==='blender'?'3D 场景可能需较长渲染时间，V1 为可选高级引擎。':engine==='motion_canvas'?'支持可编程 MG 动效和字幕节奏。':engine==='moneyprinterturbo'?'用于素材混剪、字幕及配音。禁止使用其自动发布功能。':'支持真实录屏、混剪和可编辑时间线。'}</div></div>
 <div class="inspector-input"><label>字幕示例</label><input value="这是一条使用真实品牌资料的宣传视频" disabled></div>
 <div class="divider"></div>${btn('请求 AI 局部修改','revise-shot','btn primary')}<div class="tiny" style="margin-top:12px">引擎选择会更新本地示例状态；不会调用模型或渲染文件。</div></div></div>
 <div class="panel-note"><strong>事实与版权：</strong>真实软件演示镜头必须使用有依据的截图或录屏，合成画面不能虚构产品能力。生成资产需要核验授权；最终由用户在官方平台亲自发布。</div>`;
}
function storyboard(){return head('多类型宣传视频分镜','分镜可选择不同的制作引擎，支持混合编排和局部重做。',`${link('/studio/video/1','返回视频编辑器','btn primary')}`,'MULTI ENGINE STORYBOARD')+`<div class="g3">${EXAMPLE.shots.map((x,i)=>`<div class="card"><div class="space-between">${pill(`镜头 ${i+1}`)}<span class="muted small">${x[1]}</span></div><div style="height:135px;border:1px solid var(--line);border-radius:11px;display:grid;place-items:center;background:radial-gradient(circle at 60% 25%,#29436e,#0b1221)"><div style="border-radius:9px;padding:17px 25px;transform:rotate(${-10+i*4}deg);color:#bad1fa;background:#364b74aa;border:1px solid #849fe965">PROMO · SCENE 0${i+1}</div></div><h3>${x[0]}</h3><div class="small muted">制作引擎：${SHOT_ENGINES.find(y=>y[0]===(state.shotEngines?.[i]||'openfilm'))?.[1]}</div><div style="margin-top:12px">${btn('编辑此镜头','select-storyboard','btn small',`data-shot="${i}"`)}</div></div>`).join('')}</div>`}
function renderVideo(){return head('视频渲染与导出','正式版使用渲染 Worker 处理成片和字幕。原型只演示状态流转。',`${link('/studio/video/1','返回剪辑器')}`,'RENDER QUEUE')+`<div class="split"><div class="card"><div class="card-title"><h2>当前渲染任务</h2>${pill(state.videoRender==='not-started'?'未开始':state.videoRender==='done'?'示意完成':'演示进行中',state.videoRender==='done'?'green':'gold')}</div><div class="g3"><div><div class="tiny">视频长度</div><div class="bold">${state.duration} 秒</div></div><div><div class="tiny">比例</div><div class="bold">${state.ratio}</div></div><div><div class="tiny">输出格式</div><div class="bold">MP4 / H.264（计划）</div></div></div><div class="divider"></div><div class="progress-line"><span style="width:${state.videoRender==='not-started'?0:state.videoRender==='done'?100:45}%"></span></div><div class="small muted" style="margin-top:11px">${state.videoRender==='not-started'?'尚未触发演示任务':state.videoRender==='done'?'流程演示结束；并未创建 MP4 文件':'正在模拟流程阶段，不会使用算力或创建文件'}</div><div style="margin-top:18px">${btn('演示渲染工作流','simulate-render','btn primary')}</div></div>${card('渲染前质量核对',`<div class="checklist">${[['真实软件素材','需实际上传并验证'],['配音和音效授权','需检查商业授权'],['字幕与事实一致','需要逐帧检查'],['AI 内容声明','发布平台最终由用户确认']].map((x,i)=>`<div class="checkline">${ic(i===0?'alert':'check',15)} <div><strong>${x[0]}</strong><div class="tiny">${x[1]}</div></div></div>`).join('')}</div><div class="panel-note warning-note" style="margin-top:18px">原型没有视频渲染后端，不提供虚假的 MP4 下载链接。正式成片将由真实渲染服务导出。</div>`)}</div>`}
function compliance(){return head('内容合规审核','AI 审核是发布前的内部预审，不是平台官方批准。素材、功能描述、版权和 AI 标识都要检查。',`${link('/compliance/1','查看详细报告','btn primary')}`,'COMPLIANCE REVIEW')+`<div class="g3 section">${metricsCard('待处理','1','需补充来源或人工确认','alert')}${metricsCard('预审待确认','2','示例状态，尚无后台审核','shield')}${metricsCard('高风险拦截','0','原型没有实际检测服务','check')}</div><div class="split">${card('内容审查队列',`<div class="stack">${[['宣传片 · 软件功能展示','需要用户检查真实界面与 AI 标识','待人工复核','gold'],['面试问答技巧图文','宣传结果承诺与真实性预审','演示待检查','blue'],['软件介绍主视觉','素材版权及许可证明','待补充','gold']].map(x=>`<div class="item-row"><div class="iconbox">${ic('shield')}</div><div class="item-info"><strong>${x[0]}</strong><div class="sub">${x[1]}</div></div>${pill(x[2],x[3])}</div>`).join('')}</div>`,link('/compliance/1','查看证据','action-link'))}${card('内部预审规则',`<div class="stack">${[['功能真实性','CG 镜头对应真实 UI 与资料来源'],['商业版权','字体、图片、音效、Logo 的商业许可'],['AI 内容标识','记录生成部分；发布时按平台功能声明'],['平台文案规则','夸大承诺、违规导流和不合规营销']].map(x=>`<div class="item-row"><div class="iconbox">${ic('check')}</div><div class="item-info"><strong>${x[0]}</strong><div class="sub">${x[1]}</div></div></div>`).join('')}</div><div class="panel-note warning-note" style="margin-top:13px"><strong>重要：</strong>用户自行在官方客户端发布，也必须符合目标平台规则。</div>`)}</div>`}
function complianceDetail(){return head('宣传片 · 合规报告','检查范围和依据均应可追溯，以下是用于 UI 设计的示例结果。',`${link('/compliance','返回审核队列')}${link('/publish/package/1','查看发布包','btn primary')}`,'AUDIT EVIDENCE')+`<div class="split"><div class="stack-lg">${card('检查结果',`<div class="risk ok">${ic('check')}<div><strong>宣传方向：未发现明显不适宜描述</strong><p>仅为展示规则形态的演示结论；没有实际执行文本模型审核。</p></div></div><div class="risk" style="margin-top:12px">${ic('alert')}<div><strong>真实 UI 与功能证据：需人工核对</strong><p>确保字幕与真实版本功能一一对应，不得伪造功能效果。</p></div></div><div class="risk" style="margin-top:12px">${ic('alert')}<div><strong>AI 内容标识：发布时须由用户确认</strong><p>检查适用的显式/隐式标识要求，在官方平台选择相应的 AI 内容声明。</p></div></div><div class="risk" style="margin-top:12px">${ic('alert')}<div><strong>声音与图片商业版权：未提供授权证明</strong><p>需将素材许可和用途范围保存在品牌素材库。</p></div></div>`)}${card('审核依据',`<div class="table-wrap"><table class="table"><tr><th>类别</th><th>依据</th><th>验证状态</th></tr>${[['品牌功能','用户上传的产品介绍和真实 UI','待核实'],['图文内容','平台现行规则与用户人工检查','待核实'],['AI 生成声明','中国 AI 生成内容标识相关规定','需用户确认']].map(x=>`<tr>${x.map(y=>`<td>${y}</td>`).join('')}</tr>`).join('')}</table></div>`)}</div>${card('处理建议',`<div class="panel-note"><strong>建议动作</strong><p class="small">补充真实软件界面；核对所有宣传卖点；记录素材授权；检查平台当前官方要求后手动发布。</p></div><div class="divider"></div><div class="small muted">内部审核结论与平台官方判定是两个独立状态，不能把“预审通过”写成“平台审核通过”。</div>${btn('标记已人工核对（演示）','confirm-compliance','btn primary')}`)}</div>`}
function publish(){let ready=state.drafts.filter(d=>d.status==='待人工发布');return head('人工发布中心','AI 只准备内容与发布资料；你本人使用平台官方客户端或官网上传并公开发布。',`${link('/publish/guide/douyin',ic('help')+' 发布指引')}${link('/publish/package/1',ic('download')+' 查看发布包','btn primary')}`,'MANUAL PUBLISH CENTER')+`<div class="panel-note section"><div class="flex-row">${ic('shield',18)}<strong>账号安全边界</strong></div>不连接社媒账号、不保存平台登录凭据、不操作第三方页面、不自动发帖；“手动发布登记”只是用户自报，未经平台验证。</div><div class="g3 section">${metricsCard('等待你手动发布',ready.length,'资料准备完成，等待你操作','clock')}${metricsCard('你已登记发布',state.published.length,'用户填写，不属于平台验证回执','check')}${metricsCard('需人工核实',1,'素材来源、AI 标识与平台规则','shield')}</div><div class="split">${card('今天的待发布作品',`<div class="stack">${ready.map((d,i)=>`<div class="item-row"><div style="width:76px;height:90px;flex:none">${poster(i%2?'mint':'')}</div><div class="item-info"><strong>${esc(d.title)}</strong><div class="sub">${esc(d.type)} · 建议平台 ${esc(d.platform)} · ${esc(d.date)}</div><div style="margin-top:8px">${pill('等待你发布','gold')}</div></div>${link('/publish/package/1','查看资料','btn small')}</div>`).join('')}</div>`,link('/campaigns','全部作品','action-link'))}${card('手动发布 · 5 步',`<div class="timeline">${[['1. 预览并核实内容','真实功能、准确文案与授权素材'],['2. 下载成品和复制文案','下载 MP4 / 图片 / 封面 / 标题'],['3. 打开官方平台','用户自主登录并上传'],['4. 选择必要的 AI 声明','按平台当时的功能和规则处理'],['5. 回来登记和导入数据','保存真实来源以便 AI 学习']].map((x,i)=>`<div class="event"><span class="marker">${i+1}</span><div><strong>${x[0]}</strong><div class="meta">${x[1]}</div></div></div>`).join('')}</div>`,link('/publish/guide/douyin','详细发布教程','action-link'))}</div>`}
function packageDetail(){const names=['我核对了真实软件功能与价格','已核实所有图片/音乐/字体的使用权限','检查了平台最新广告和内容要求','确认了视频 AI 生成标识及发布声明','我会亲自使用官方平台上传并发布'];return head('发布资料包 · CG 软件介绍','下载素材、复制文案，然后由你本人在平台官方客户端进行发布。',`${link('/publish','返回发布中心')}${btn(ic('download')+' 导出演示清单','download-package','btn primary')}`,'MANUAL HANDOFF PACKAGE')+`<div class="content-pair section"><div class="stack-lg">${card('视频与封面预览',`${renderStage()}<div class="flex-row" style="margin-top:14px">${pill('宣传片 · 30s')}${pill('建议 9:16')}${pill('演示占位','gold')}</div><div class="panel-note warning-note" style="margin-top:12px">当前原型不包含真实 MP4 视频。下载按钮仅会生成标题、简介和发布步骤的演示文本文件；正式版需要渲染后端提供真正成品。</div>`)}${card('发布文案',`<div class="field"><label>标题</label><div class="copy-area">${esc(state.editedTitle)}</div>${btn(ic('copy')+' 复制标题','copy-title','btn small')}</div><div class="field" style="margin-top:15px"><label>简介和标签</label><div class="copy-area">${esc(state.editedCopy)}</div>${btn(ic('copy')+' 复制正文','copy-desc','btn small')}</div>`)}</div><div class="stack-lg">${card('发布前检查清单',`<div class="checklist">${names.map((x,i)=>`<label class="checkline"><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}><span>${x}</span></label>`).join('')}</div><div class="divider"></div><div class="small muted">勾选 ${state.checks.filter(Boolean).length}/5 项。此清单为个人核对，不是平台授权或安全保证。</div><div class="quick-actions">${link('/publish/guide/douyin',ic('book')+' 打开发布指引','btn')}${btn('我已手动发布','start-record','btn primary')}</div>`)}${card('发布状态说明',`<div class="item-row"><span class="marker">${ic('clock')}</span><div class="item-info"><strong>等待用户手动发布</strong><div class="sub">AI 不会上传、填写账号内容或点击发布。</div></div></div><div class="item-row"><span>${ic('shield')}</span><div class="item-info"><strong>尚未获得平台验证</strong><div class="sub">用户登记只用于个人记录和后续分析。</div></div></div>`)}</div></div>`}
function guide(){return head('官方平台人工发布指引','这里仅提供操作说明。平台界面和 AI 标识入口可能变化，请以当前官方说明为准。',`${link('/publish/package/1','返回发布包')}`,'HUMAN PUBLISH GUIDE')+`<div class="steps-row section">${[['核实素材','检查视频/图文、功能和商业授权'],['下载内容','将视频、封面保存在自己的设备'],['进入官方平台','自己打开官方 App 或官方网站'],['自行上传与发布','添加标题、标签，确认 AI 声明'],['返回登记','记录真实发布日期和作品链接']].map((x,i)=>`<div class="step-card"><div class="num">0${i+1}</div><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div><div class="split">${card('平台操作注意事项',`<div class="stack"><div class="risk">${ic('alert')}<div><strong>小红书</strong><p>用户自行打开官方客户端发布；不要依赖第三方脚本代发。图文、营销内容与 AI 生成声明以现行规则为准。</p></div></div><div class="risk">${ic('alert')}<div><strong>抖音</strong><p>用户本人上传视频，检查版权、宣传用语及 AI 内容标识。AI 预审不代表官方审核通过。</p></div></div><div class="risk">${ic('alert')}<div><strong>闲鱼</strong><p>若将来扩展商品内容，核对禁售品、真实描述、资质与交易规则，仍由用户自行发布。</p></div></div></div>`)}${card('发布后做什么？',`<p class="muted small">完成平台官方发布后，回来登记作品链接或发布时间。以后从官方后台导出数据或者手动填入指标。</p>${link('/publish/record/1','登记我已发布','btn primary')}<div class="divider"></div><div class="panel-note">软件不会通过页面自动化确认你的发布是否成功。作品链接只能作为用户自报线索，不等于平台已审核验证。</div>`)}</div>`}
function record(){return head('登记你已经手动发布的内容','登记动作只会更新本软件内的记录，不会向平台发送任何内容。',`${link('/publish/package/1','返回发布包')}`,'USER REPORTED RECORD')+`<div class="content-pair"><div class="card"><div class="field"><label for="record-platform">发布平台</label><select id="record-platform"><option>抖音</option><option>小红书</option><option>闲鱼</option><option>官网/博客</option></select></div><div class="field" style="margin-top:14px"><label for="record-date">实际发布日期</label><input id="record-date" type="date" value="${state.recordDate}"></div><div class="field" style="margin-top:14px"><label for="record-url">作品链接（可选）</label><input id="record-url" type="url" value="${esc(state.recordUrl)}" placeholder="在官方平台复制作品链接"></div><div class="checkline" style="margin-top:16px"><input id="record-confirm" type="checkbox" ${state.confirmSource?'checked':''}><label for="record-confirm">我确认已在平台官方界面自行提交并完成发布操作。本记录为用户自行登记，并非平台验证回执。</label></div><div style="margin-top:20px">${btn('保存手动发布记录','save-record','btn primary')}</div></div>${card('记录说明',`<div class="panel-note"><strong>为什么要登记？</strong><p>AI 需要知道哪条作品已经由你发布，以及何时观察该作品的数据，才能持续改善选题。</p></div><div class="divider"></div><div class="small muted">平台名称、日期与作品链接属于用户填写数据。本软件无法保证用户录入信息与平台的实际审核状态一致。</div>${state.published.length?`<div class="divider"></div><strong class="small">最近登记记录</strong>${state.published.slice(-3).reverse().map(x=>`<div class="item-row"><div class="item-info"><strong>${esc(x.platform)}</strong><div class="sub">${esc(x.date)} · 用户自行登记</div></div>${pill('未核验','gold')}</div>`).join('')}`:''}`)}</div>`}
function analytics(){let total=state.metrics.length;let sum=k=>state.metrics.reduce((a,b)=>a+(Number(b[k])||0),0);const has=total>0;return head('运营数据分析','只使用你提供的真实指标；没有数据时不会自动编造平台曝光量或涨粉。',`${link('/analytics/import',ic('upload')+' 导入真实数据','btn primary')}`,'ANALYTICS & PROVENANCE')+`<div class="panel-note section"><strong>数据来源：</strong>${has?`你在本原型中录入/导入的 ${total} 条记录，仅保存在浏览器演示状态中。`:'尚未提供真实平台数据。下方仅展示空状态和可导入的指标，不显示虚构的效果增长。'}</div><div class="g4 section">${metricsCard('数据记录',String(total),'用户提供的统计记录','file')}${metricsCard('已录入播放/阅读',has?sum('views').toLocaleString():'—','不同平台不可直接比较','chart')}${metricsCard('已录入收藏',has?sum('saves').toLocaleString():'—','仅导入的数据','spark')}${metricsCard('已录入有效咨询',has?sum('leads').toLocaleString():'—','按用户填报口径','user')}</div><div class="split">${card('最近数据记录',has?`<div class="table-wrap"><table class="table"><tr><th>来源</th><th>平台</th><th>播放/阅读</th><th>收藏</th><th>咨询</th></tr>${state.metrics.slice(-8).reverse().map(m=>`<tr><td>${esc(m.source)}</td><td>${esc(m.platform)}</td><td>${m.views}</td><td>${m.saves}</td><td>${m.leads}</td></tr>`).join('')}</table></div>`:`<div class="empty">${ic('chart')}<strong>暂无平台数据</strong><div class="small">可以从官方后台导出报表，再导入这里。</div>${link('/analytics/import','导入第一条数据','btn small')}</div>`)}${card('成长回路',`<div class="timeline">${[['运营内容已准备','AI 自动生成符合品牌事实的作品'],['用户完成官方发布','在平台手动上传、发布并回来登记'],['合法数据回流','用户手填或上传官方报表'],['AI 生成下一轮建议','以实际数据和来源为依据']].map((x,i)=>`<div class="event"><span class="marker">${i+1}</span><div><strong>${x[0]}</strong><div class="meta">${x[1]}</div></div></div>`).join('')}</div>${link('/growth','查看成长建议','btn')}`)}</div>`}
function importData(){return head('导入平台运营数据','支持手工录入、官方 CSV/XLSX 报表的字段映射设计；此原型可读取 CSV，暂不解析 XLSX。',`${link('/analytics','返回数据看板')}`,'DATA IMPORT')+`<div class="split"><div class="stack-lg">${card('方式一 · 手工录入',`<div class="form-grid"><div class="field"><label for="import-platform">平台</label><select id="import-platform"><option ${state.importPlatform==='小红书'?'selected':''}>小红书</option><option ${state.importPlatform==='抖音'?'selected':''}>抖音</option><option>官网</option></select></div><div class="field"><label>数据类型</label><input value="用户手工录入" disabled></div><div class="field"><label for="import-views">阅读/播放数</label><input id="import-views" type="number" min="0" value="${esc(state.importViews)}" placeholder="填写真实统计"></div><div class="field"><label for="import-saves">收藏数</label><input id="import-saves" type="number" min="0" value="${esc(state.importSaves)}" placeholder="填写真实统计"></div><div class="field"><label for="import-leads">有效咨询数</label><input id="import-leads" type="number" min="0" value="${esc(state.importLeads)}" placeholder="按你的真实口径"></div></div><div class="panel-note warning-note" style="margin-top:14px">只有实际观察到的指标才填写。来源统一标记“用户手工录入”。</div><div style="margin-top:14px">${btn(ic('check')+' 保存这组数据','save-metrics','btn primary')}</div>`)}${card('方式二 · 从 CSV 导入',`<p class="small muted">本地演示支持含 <code>platform,views,saves,leads</code> 的 UTF-8 CSV。文件只在本浏览器中解析，不上传服务器。</p><div class="field"><label for="csv-file">上传 CSV 报表</label><input type="file" accept=".csv,text/csv" id="csv-file"></div><div class="flex-row" style="margin-top:14px">${btn('下载 CSV 模板','download-csv','btn')}${btn('读取 CSV','read-csv','btn primary')}</div><div class="tiny" style="margin-top:13px">生产版需实现 XLSX、平台报表字段映射、重复导入检查及隐私保护。</div>`)}</div>${card('数据正确性规则',`<div class="stack">${[['真实来源','标注用户录入或官方导出报表'],['时间窗口','对比时需使用相近成熟度的作品'],['平台区别','不同平台的阅读、播放不直接合并推断'],['缺失数据','展示“未导入”，不设为零'],['异常处理','不接受负数、伪造数据或来源不明记录']].map(x=>`<div class="item-row"><span style="color:var(--teal)">${ic('check',15)}</span><div class="item-info"><strong>${x[0]}</strong><div class="sub">${x[1]}</div></div></div>`).join('')}</div><div class="divider"></div>${link('/growth','导入后看成长报告','btn')}`)}</div>`}
function growth(){let samples=state.metrics.length;return head('成长与策略复盘','把数据、假设与用户修改真正转化为下一轮选题，而不是仅写一篇周报。',`${link('/growth/memory',ic('brain-circuit')+' 长期记忆','btn')}${link('/topics','查看新选题','btn primary')}`,'CREATOR LEARNING')+`<div class="g3 section">${metricsCard('已导入真实指标',samples+' 条','全部保留来源和采样时间','chart')}${metricsCard('稳定创作人设','1 套','品牌事实由用户维护','bot')}${metricsCard('等待验证的假设','3 项','样本少时不输出确定结论','bulb')}</div><div class="split"><div class="stack-lg">${card('本周洞察',`${samples===0?'<div class="empty">'+ic('chart')+'<strong>还不能进行数据驱动的效果判断</strong><div class="small">导入作品真实数据后，AI 才能比较内容方向。</div></div>':`<div class="learning-highlight"><strong>已有用户提供的指标</strong><p>当前共有 ${samples} 条输入记录。只有在样本量和作品成熟时间可比时，才能研究哪个方向更有效；目前只能形成候选假设。</p></div>`}<div class="divider"></div><strong class="small">待验证策略假设</strong>${[['教程优先','更具体的使用教程可能带来高意向咨询'],['视觉多样性','多风格宣传视频 与知识图文交替可能减少重复感'],['证据完整','减少无法核实的卖点可能提高内容质量']].map(x=>`<div class="item-row"><div class="item-info"><strong>${x[0]}</strong><div class="sub">${x[1]}</div></div>${pill('待验证','gold')}</div>`).join('')}`)}${card('下一周策略建议',`<div class="panel-note"><strong>候选而非自动生效：</strong>建议保持使用教程、软件 CG 展示和面试知识三类栏目，等积累更多真实指标后再调整比例。</div><div class="quick-actions">${btn('采纳候选策略（演示）','approve-strategy','btn primary')}${btn('保持现有策略','decline-strategy','btn')}</div>`)}</div>${card('证据与版本',`<div class="item-row"><div class="iconbox">${ic('history')}</div><div class="item-info"><strong>创作者策略 V1</strong><div class="sub">初始品牌设定 · 已固定</div></div>${pill('当前','green')}</div><div class="item-row"><div class="iconbox">${ic('bulb')}</div><div class="item-info"><strong>候选策略 V2</strong><div class="sub">等待用户确认，尚未应用</div></div>${pill('建议','gold')}</div><div class="divider"></div><div class="small muted">未来版本的每条策略变更都应附统计来源、样本量、理由和回滚入口。</div>${link('/growth/memory','记忆与版本管理','btn')}`)}</div>`}
function memory(){return head('长期记忆与策略版本','不是无限增长的聊天记录，而是有证据、可纠正、可撤回的结构化记忆。',`${link('/growth','返回成长报告')}`,'LONG-TERM MEMORY')+`<div class="g3">${card('品牌事实 · 用户锁定',`<div class="stack">${[['品牌名称','有招｜AI 面试智能体'],['真实功能','需以用户提供的当前版本为准'],['不得声称','保证录取、真实用户好评等未核实信息']].map(x=>`<div class="item-row"><div class="item-info"><strong>${x[0]}</strong><div class="sub">${x[1]}</div></div>${ic('lock',14)}</div>`).join('')}</div>${link('/brand','编辑品牌事实','btn small')}`)}${card('创作偏好 · 可调整',`<div class="stack">${[['不使用真人出镜','偏好 CG 软件动画'],['视觉风格','深色玻璃 · 苹果极简'],['表达方式','客观、简洁、减少营销腔']].map(x=>`<div class="memory-tag">${x[0]}<div class="tiny">${x[1]}</div></div>`).join('')}</div>${link('/creator/edit','调整人设','btn small')}`)}${card('运营经验 · 证据驱动',`<div class="empty">${ic('bulb')}<strong>尚无可靠的长期结论</strong><div class="small">在导入可对比的数据后，才会形成可解释的学习记录。</div>${link('/analytics/import','导入真实数据','btn small')}</div><div class="divider"></div><div class="small muted">删除学习记忆不等于删除原始数据；生产版需分别提供清理和纠错能力。</div>`)}</div>`}
function brand(){return head('品牌与真实产品事实库','宣传语、视频镜头和每条内容都应基于你确认过的真实产品资料。',`${btn('保存品牌资料（演示）','save-brand','btn primary')}`,'BRAND FACTS')+`<div class="split"><div class="stack-lg">${card('品牌资料',`<div class="form-grid"><div class="field"><label>品牌或软件名</label><input id="brand-name" value="${esc(state.brand)}"></div><div class="field"><label>软件官网</label><input placeholder="https://软件官网（可选）"></div></div><div class="field" style="margin-top:15px"><label>目标用户</label><textarea>${esc(state.target)}</textarea></div>`)}${card('已确认功能与宣传禁令',`<div class="checklist">${EXAMPLE.features.map(x=>`<div class="checkline">${ic('check',15)}<span>${x} <span class="tiny">（原型说明，需核实）</span></span></div>`).join('')}</div><div class="divider"></div><div class="risk">${ic('alert')}<div><strong>严禁无依据宣传</strong><p>100% 拿 Offer、全网第一、用户真实好评、虚构功能、假造软件界面。</p></div></div>`)}</div>${card('素材证据与版本',`<div class="item-row"><span style="color:var(--primary)">${ic('image')}</span><div class="item-info"><strong>主界面截图</strong><div class="sub">未上传，需要真实来源</div></div>${pill('缺少','gold')}</div><div class="item-row"><span style="color:var(--primary)">${ic('video')}</span><div class="item-info"><strong>操作录屏</strong><div class="sub">未上传，需要真实来源</div></div>${pill('缺少','gold')}</div><div class="item-row"><span style="color:var(--primary)">${ic('file')}</span><div class="item-info"><strong>版本与功能说明</strong><div class="sub">需要用户核实发布日期和适用版本</div></div>${pill('待确认','gold')}</div><div class="divider"></div>${link('/studio/assets','打开素材库','btn')}`)}</div>`}
function settings(){return head('产品设置','管理外观、创作预算、提醒与数据隐私。这里没有社媒账号登录或 Cookie 配置。',`${btn('恢复演示初始状态','reset-demo','btn danger')}`,'PREFERENCES')+`<div class="split"><div class="stack-lg">${card('外观与体验',`<div class="setting-row"><div><strong>浅色主题</strong><p>页面背景与卡片切换至浅色</p></div><button class="toggle ${state.theme==='light'?'on':''}" data-action="theme" aria-label="切换浅色主题"></button></div><div class="setting-row"><div><strong>通知提醒</strong><p>原型中的待办通知，正式版可选择站内/邮件</p></div><button class="toggle ${state.alerts?'on':''}" data-action="toggle-alerts" aria-label="开关通知提醒"></button></div>`)}${card('预算和模型',`<div class="setting-row"><div><strong>月度内容制作预算</strong><p>包含模型调用、视频渲染及存储成本</p></div><strong>¥${state.budget}</strong></div><div class="setting-row"><div><strong>模型供应商</strong><p>正式版支持用户自带合法 API Key，并限制密钥展示</p></div>${pill('待接入','gold')}</div>${link('/creator/edit','调整预算','btn')}`)}</div>${card('隐私与合规边界',`<div class="stack">${[['不采集社媒登录凭据','不存储平台密码、Cookie 或会话数据'],['不代用户发布','没有对第三方平台的写入接口'],['真实数据由用户提供','正式版提供来源和删除机制'],['AI 预审不等于平台审核','发布前始终由用户检查规则与内容标识']].map(x=>`<div class="item-row"><span style="color:var(--teal)">${ic('check',16)}</span><div class="item-info"><strong>${x[0]}</strong><div class="sub">${x[1]}</div></div></div>`).join('')}</div><div class="divider"></div>${link('/help','查看使用手册','btn')}`)}</div>`}
function help(){return head('使用手册与帮助中心','以普通用户能操作的语言，解释创建、制作、手动发布和成长复盘。',`${link('/onboarding/welcome',ic('spark')+' 新手引导','btn primary')}`,'PRODUCT HANDBOOK')+`<div class="docs-layout"><aside class="card toc"><strong>目录</strong>${[['start','新手六步入门'],['creator','持续 AI 创作者'],['studio','图文与 宣传视频制作'],['manual','人工发布操作'],['data','导入运营数据'],['learning','长期成长与复盘'],['safety','安全与合规'],['faq','常见问题']].map(x=>`<a href="#${x[0]}" data-doc-anchor="${x[0]}">${x[1]}</a>`).join('')}</aside><div class="card article-doc"><section id="doc-start"><h2>第一次使用：六步完成</h2><p>① 创建品牌事实库；② 配置 AI 创作者的人设、栏目和更新频率；③ 确认第一周计划；④ 审核图文和 宣传视频；⑤ 下载资料，在平台官方界面自行发布；⑥ 返回登记并提供真实指标。</p>${link('/onboarding/welcome','开始新手向导','btn small')}</section><section id="doc-creator"><h3>持续 AI 创作者</h3><p>创建后，正式版会按设定节奏长期生成内容。你可以暂停、恢复、修改频率和预算。暂停不影响过去已经公开发布的作品。</p>${link('/creator','查看我的创作者','btn small')}</section><section id="doc-studio"><h3>图文和 宣传片</h3><p>软件演示要以真实截图/录屏为依据。选择 2D/MG、3D/CG、卡通、录屏、AI 创意或混剪，设置时长和比例；还可在分镜中逐个更换引擎。正式版由渲染 Worker 输出 MP4；这个离线演示原型不具备实际 AI 视频生成能力。</p>${link('/studio/video/new','打开 CG 工作室','btn small')}</section><section id="doc-manual"><h3>在平台上自行发布</h3><p>先检查功能真实性、素材版权和 AI 内容标识，下载视频/图文，自己打开官方 App 上传并点击发布。回来填写实际发布平台和链接。本软件不会代你执行此操作。</p>${link('/publish/guide/douyin','查看发布步骤','btn small')}</section><section id="doc-data"><h3>导入真实数据</h3><p>使用官方后台的数据导出文件或手动录入统计。未导入时数据看板显示缺失，不展示编造指标。平台之间的播放与阅读不能直接作为同一量纲比较。</p>${link('/analytics/import','打开数据导入','btn small')}</section><section id="doc-learning"><h3>AI 如何持续成长？</h3><p>AI 保留内容假设、创作版本、用户反馈和真实指标，每周提出策略建议。数据不足时只能记录候选假设，不能凭空宣称找到流量规律。</p>${link('/growth','查看成长与复盘','btn small')}</section><section id="doc-safety"><h3>安全、合规与隐私</h3><p>人工发布减少了自动化操作风险，但无法保证账号永远不会被处罚。平台内容规范可能更新；所有宣传事实、版权素材和 AI 标识仍需你亲自复核。</p></section><section id="doc-faq"><h3>常见问题</h3><p><strong>它会帮我点发布吗？</strong>不会。你本人在平台官方界面操作。</p><p><strong>没有真实数据也会学习吗？</strong>可以记住你对内容的修改和偏好，但不能声称依据平台运营效果获得了经验。</p><p><strong>为什么原型无法下载 MP4？</strong>目前只是可点击的离线 UI 演示，没有连接真实渲染 Worker。</p><p><strong>可以离线查看更完整的手册吗？</strong>交付包 <code>docs/03_用户使用手册.md</code> 含操作细节与故障排查。</p></section></div></div>`}
function login(){return head('欢迎来到叙流','AI 长期创作与运营工作台 · 登录页设计演示。',`${link('/onboarding/welcome','体验新手流程','btn primary')}`,'SIGN IN')+`<div style="max-width:460px;margin:30px auto" class="card"><div class="brandmark" style="margin-bottom:19px">叙</div><h2>继续你的内容创作</h2><p class="muted small">正式版支持登录和工作区身份验证。当前离线原型不验证账号。</p><div class="field"><label>邮箱</label><input type="email" value="creator@example.com"></div><div class="field" style="margin-top:15px"><label>密码</label><input type="password" value="demo-only-password"></div><div style="margin-top:18px">${link('/dashboard','体验演示工作台','btn primary')}</div><p class="tiny">仅界面演示 · 不会上传账号或密码 · 不保存登录凭据</p></div>`}
function onboarding(){let r=route(),step=r==='/onboarding/welcome'?0:r==='/onboarding/brand'?1:r==='/onboarding/creator'?2:3;const steps=['产品介绍','品牌资料','创建创作者','确认计划'];return head('第一次使用 · 四步创建你的 AI 创作者','你只需要配置一次产品和运营目标，之后就能持续准备每日内容。',`${link('/dashboard','跳过并体验工作台')}`,'ONBOARDING')+`<div style="max-width:870px;margin:auto"><div class="g4 section">${steps.map((s,i)=>`<a href="#${['/onboarding/welcome','/onboarding/brand','/onboarding/creator','/onboarding/preview'][i]}" class="card condensed" style="border-color:${i===step?'var(--primary)':'var(--line)'};text-align:center"><div class="tiny">步骤 0${i+1}</div><strong class="small">${s}</strong></a>`).join('')}</div>${step===0?`<div class="hero" style="min-height:285px"><div style="max-width:540px"><div class="pill green" style="margin-bottom:19px">${ic('spark',12)} 每日自动创作 · 用户本人发布</div><h2>养成一个持续工作的<br>AI 软件内容创作者。</h2><p>AI 写选题、做图文、制作宣传视频；你审核、手动发布，再把真实运营数据交回 AI 形成长期成长。</p>${link('/onboarding/brand','开始创建 '+ic('arrow',14),'btn primary')}</div></div>`:step===1?`<div class="card"><h2>第 1 步 · 填写真实产品资料</h2><p class="muted small">后续视频和文案会依据这份事实库，禁止虚构软件功能。</p><div class="form-grid"><div class="field"><label>软件名</label><input id="onboard-brand" value="${esc(state.brand)}"></div><div class="field"><label>软件官网（可选）</label><input placeholder="https://example.com"></div></div><div class="field" style="margin-top:14px"><label>主要目标用户</label><textarea>${esc(state.target)}</textarea></div><div class="panel-note" style="margin-top:13px">真实 UI 截图、录屏、Logo 和许可文件可在品牌素材库进一步完善。</div><div class="quick-actions">${btn('保存并继续','onboard-brand-next','btn primary')}</div></div>`:step===2?`<div class="card"><h2>第 2 步 · 设定 AI 创作者人设</h2><p class="muted small">可以在之后随时修改，历史数据与作品不会丢失。</p><div class="form-grid"><div class="field"><label>创作者名称</label><input id="onboard-creator" value="${esc(state.creatorName)}"></div><div class="field"><label>更新节奏</label><select id="onboard-frequency"><option>每天 1 条</option><option>每周 5 条</option></select></div><div class="field"><label>主视觉方向</label><select><option>混合宣传视频 · 不使用真人出镜</option></select></div><div class="field"><label>公开发布方式</label><input value="本人通过官方平台手动发布" disabled></div></div><div class="quick-actions">${btn('保存并预览计划','onboard-creator-next','btn primary')}</div></div>`:`<div class="card"><h2>第 3 步 · 确认首周的创作计划</h2><p class="muted small">所有选题均为演示样例；正式版需要 AI 根据真实资料和用户目标制定。</p><div class="table-wrap"><table class="table"><tr><th>日期</th><th>推荐内容</th><th>形式</th></tr>${EXAMPLE.topics.slice(0,6).map((x,i)=>`<tr><td>第 ${i+1} 天</td><td><strong>${esc(x.title)}</strong></td><td>${x.kind}</td></tr>`).join('')}</table></div><div class="panel-note" style="margin-top:12px">确认计划只是启用后台创作日程，不会启动任何社媒自动发布。</div><div style="margin-top:15px">${btn('确认计划并进入工作台','confirm-plan','btn primary')}</div></div>`}</div>`}

function opsDiagnostics(){return head('诊断与维护中心','跨服务追踪、失败镜头、运行版本和回滚建议。这里所有记录均为虚构演示数据。','', 'ENGINEERING OBSERVABILITY')+
 `<div class="g3 section">${card('演示任务状态',`<div class="small muted">run_demo_20261105</div><div style="font-size:22px;font-weight:700;margin:10px 0">第 4 镜头失败</div>${pill('示例 · 非真实日志','gold')}`)}${card('错误类别',`<div style="font-size:13px;font-weight:700;margin:10px 0">VID_RENDER_RESOURCE_EXHAUSTED</div><div class="small muted">演示错误码 · 不代表真实 GPU 状态</div>`)}${card('运行版本',`<div class="small muted">release: demo-not-a-real-release</div><div class="small muted">Video IR: design-v1</div><div class="small muted">Provider: wan_worker (虚构)</div>`)}</div>`+
 `<div class="split section">${card('执行链 · 首次失败阶段',`<div class="stack">${[['运营选题','完成','green'],['脚本草案','完成','green'],['分镜规划','完成','green'],['场景渲染 / scene_04','失败','gold'],['合成输出','依赖前序而跳过','blue']].map(x=>`<div class="item-row"><span style="color:var(--primary)">${ic(x[2]==='green'?'check':'alert',16)}</span><div class="item-info"><strong>${x[0]}</strong></div>${pill(x[1],x[2])}</div>`).join('')}</div><div class="panel-note warning-note" style="margin-top:14px">只展示业务状态和错误类别，实际根因必须根据 OpenTelemetry Trace 和 Worker 资源监控证明。</div>`)}${card('诊断与维护动作',`<div class="stack"><div class="item-row"><span>${ic('info')}</span><div class="item-info"><strong>优先确认的证据</strong><div class="sub">GPU 实际内存、Provider 错误原文、shot_revision、计费回执</div></div></div><div class="item-row"><span>${ic('history')}</span><div class="item-info"><strong>版本追溯</strong><div class="sub">应用 SHA / Agent / Prompt / 模型 / 模板 / IR</div></div></div><div class="item-row"><span>${ic('lock')}</span><div class="item-info"><strong>权限要求</strong><div class="sub">线上重试、部署或费用操作必须由授权用户执行</div></div></div></div><div class="divider"></div>${btn(ic('copy',14)+' 复制演示诊断编号','copy-demo-diagnostic','btn')}<div style="margin-top:10px">${link('/help','普通用户如何处理失败？','btn')}</div>`)} </div>`+
 `<div class="panel-note section">本页是 V2.3 工程后台的静态 UI 预览：不接收或泄露真实用户日志，不会调用重试、生产部署或回滚接口。正式功能需接入授权诊断 API 和完整测试。</div>`}

function genericFallback(){return head('页面不存在','请从侧栏重新选择功能。',link('/dashboard','返回总览'),'NOT FOUND')}
const VIEWS={
 '/auth/login':login,'/onboarding/welcome':onboarding,'/onboarding/brand':onboarding,'/onboarding/creator':onboarding,'/onboarding/preview':onboarding,
 '/dashboard':dashboard,'/creator':creator,'/creator/edit':creatorEdit,'/creator/activity':activity,'/calendar':calendar,'/topics':topics,'/topics/1':topicDetail,'/campaigns':campaigns,
 '/studio/article/1':article,'/studio/covers':covers,'/studio/assets':assets,'/studio/video/new':videoNew,'/studio/video/1':videoEditor,'/studio/video/1/storyboard':storyboard,'/studio/video/1/render':renderVideo,
 '/compliance':compliance,'/compliance/1':complianceDetail,'/publish':publish,'/publish/package/1':packageDetail,'/publish/guide/douyin':guide,'/publish/record/1':record,
 '/analytics':analytics,'/analytics/import':importData,'/growth':growth,'/growth/memory':memory,'/brand':brand,'/settings':settings,'/ops/diagnostics':opsDiagnostics,'/help':help
};
function render(){document.body.className=state.theme;renderSidebar();renderTopbar();const r=route();document.getElementById('main').innerHTML=(VIEWS[r]||genericFallback)();document.title=`${PAGE_LIST.find(x=>x[0]===r)?.[1]||'创作者工作台'} · 叙流 AI Creator`}
function popup(title,body,footer=''){document.getElementById('overlay-root').innerHTML=`<div class="modal-backdrop" data-modal-backdrop="1"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="space-between"><h2>${title}</h2>${btn(ic('close',18),'close-modal','btn ghost icon-only')}</div>${body}<div class="modal-footer">${footer||btn('关闭','close-modal','btn')}</div></div></div>`;const input=document.querySelector('.modal input');input?.focus()}
const closePopup=()=>{document.getElementById('overlay-root').innerHTML=''};
const downloadText=(name,text,kind='text/plain;charset=utf-8')=>{const blob=new Blob([text],{type:kind});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)};
const value=id=>document.getElementById(id)?.value||'';
function copyText(s){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(s).then(()=>toast('已复制到剪贴板')).catch(()=>fallbackCopy(s));else fallbackCopy(s)}
function fallbackCopy(s){let a=document.createElement('textarea');a.value=s;document.body.appendChild(a);a.select();try{document.execCommand('copy');toast('已复制文本')}catch(e){toast('无法调用剪贴板，请手动复制')}a.remove()}
function addMetric(m){const x={platform:m.platform||'未指定',source:m.source,views:Number(m.views)||0,saves:Number(m.saves)||0,leads:Number(m.leads)||0,observed_at:new Date().toISOString()};set({metrics:[...state.metrics,x]});toast('指标已加入本地原型演示，不会上传到服务器')}
const actions={
 menu:()=>document.getElementById('sidebar').classList.toggle('open'),
 workspace:()=>popup('选择工作区',`<p>当前仅演示一个工作区：有招｜AI 面试智能体。</p><p>正式版支持在多个品牌之间切换，但 V1 先实现一个品牌完整闭环。</p>`),
 theme:()=>set({theme:state.theme==='dark'?'light':'dark'}),
 notifications:()=>popup('待办通知',`<div class="item-row"><span>${ic('send')}</span><div class="item-info"><strong>2 条内容待你手动发布</strong><div class="sub">AI 已准备发布资料。该通知只存在于演示页面。</div></div></div><div class="item-row"><span>${ic('shield')}</span><div class="item-info"><strong>真实素材需要核对</strong><div class="sub">视频素材来源、真实功能和 AI 声明请在发布前检查。</div></div></div>`,link('/publish','前往发布中心','btn primary')),
 help:()=>goto('/help'), settings:()=>goto('/settings'),
 search:()=>{popup('搜索所有 32 个设计页面',`<input id="global-search" placeholder="搜索：视频 / 发布 / 数据 / 创作者" oninput="document.querySelectorAll('.search-result').forEach(x=>x.style.display=x.textContent.includes(this.value)?'flex':'none')"><div style="max-height:410px;overflow:auto;margin-top:14px">${PAGE_LIST.map(x=>`<a href="#${x[0]}" class="item-row search-result" style="display:flex"><span>${ic('arrow',13)}</span><div class="item-info"><strong>${x[1]}</strong><div class="tiny">${x[0]}</div></div></a>`).join('')}</div>`);},
 pause:()=>popup('确认暂停持续创作？','<p>暂停后不再生成新的日更任务，也不会触发任何对外平台操作。已有草稿和用户发布记录会保留。</p>',`${btn('取消','close-modal','btn')}${btn('确认暂停','confirm-pause','btn danger')}`),
 'confirm-pause':()=>{set({paused:true});closePopup();toast('演示状态已暂停；正式版需要通知后台调度系统')},
 resume:()=>{set({paused:false});toast('演示状态已恢复；正式版需先核验预算和运营策略')},
 'save-creator':()=>{let name=value('creator-name'),b=Number(value('creator-budget'));if(!name||!Number.isFinite(b)||b<0)return toast('请填写有效的名称与预算');set({creatorName:name,frequency:value('creator-frequency'),timezone:value('creator-timezone'),budget:b,target:value('creator-target')});toast('本地演示设定已保存')},
 'select-day':el=>set({selectedDay:Number(el.dataset.day)||5}),
 'calendar-week':()=>toast('已设计周视图入口；原型当前展示月视图'),
 'add-topic':()=>popup('新增待研究选题',`<div class="field"><label>新选题标题</label><input id="new-topic" placeholder="例如：软件项目回答应该怎样练习"></div><div class="tiny" style="margin-top:12px">此入口在原型中只演示候选新增，正式版需要连接选题库。</div>`,`${btn('取消','close-modal','btn')}${btn('新增候选','confirm-add-topic','btn primary')}`),
 'confirm-add-topic':()=>{let n=document.getElementById('new-topic');if(!n?.value.trim())return toast('请输入标题');closePopup();toast('已记录候选演示：'+n.value.slice(0,18))},
 'generate-topics':()=>toast('当前为预设选题 UI；正式版在此调用 StrategyAgent 并展示依据'),
 tab:el=>set({contentTab:el.dataset.value}),
 'adopt-topic':()=>{toast('演示：已将选题加入待创作队列');goto('/studio/video/new')},
 'save-copy':()=>{const a=value('copy-title'),b=value('copy-body');if(!a.trim()||!b.trim())return toast('标题和正文不能为空');set({editedTitle:a,editedCopy:b});toast('文案保存于此浏览器演示状态，真实审核应重新执行')},
 'check-article':()=>{actions['save-copy']();goto('/compliance/1')},
 'use-cover':()=>toast('原型：已选中模板。正式版将生成可编辑封面。'),
 'add-asset':()=>popup('添加真实素材','<p>正式版支持用户上传真实软件截图、录屏、Logo、字体与商业授权证明。当前离线原型不会采集、保存或上传素材。</p>',link('/brand','查看品牌事实库','btn')),
 style:el=>set({style:el.dataset.style}),
 'video-mode':el=>set({videoMode:el.dataset.mode}),
 'create-video':()=>{set({duration:value('video-duration'),ratio:value('video-ratio')});goto('/studio/video/1/storyboard');toast('已创建示例分镜视图；未调用模型或生成视频')},
 'toggle-play':()=>set({playing:!state.playing}),
 shot:el=>set({selectedShot:Number(el.dataset.shot)||0}),
 'select-storyboard':el=>{set({selectedShot:Number(el.dataset.shot)||0});goto('/studio/video/1')},
 'revise-shot':()=>popup('请求 AI 修改单个镜头',`<p>针对 <strong>${esc(EXAMPLE.shots[state.selectedShot][0])}</strong> 输入你的修改要求：</p><div class="field"><textarea id="shot-instruction">镜头从右边旋转入场，减少粒子，保持软件 UI 文字清楚可读。</textarea></div><div class="panel-note" style="margin-top:12px">原型仅显示请求结构。真实模型调用、局部重渲染和成本估算在后端开发阶段实现。</div>`,`${btn('取消','close-modal','btn')}${btn('保存镜头修改请求（演示）','confirm-revise','btn primary')}`),
 'confirm-revise':()=>{closePopup();toast('已保存示例修改意图，未实际修改视频文件')},
 'simulate-render':()=>{set({videoRender:'running'});toast('开始模拟渲染阶段，不会生成 MP4');setTimeout(()=>{set({videoRender:'done'});toast('流程模拟完成；没有真正的视频成片')},1200)},
 'confirm-compliance':()=>toast('演示：已记录人工核对意图，正式版需保存审计与用户标识'),
 'copy-demo-diagnostic':()=>copyText('run_demo_20261105 / 0123456789abcdef0123456789abcdef (DEMO ONLY)'),
 'copy-title':()=>copyText(state.editedTitle),
 'copy-desc':()=>copyText(state.editedCopy),
 'download-package':()=>downloadText('有招_人工发布资料包_演示.txt',`【演示发布包 / 不含 MP4】\n作品：${state.editedTitle}\n\n简介：\n${state.editedCopy}\n\n说明：AI 只负责准备资料，用户本人在第三方平台官方客户端发布；宣传视频需从正式渲染服务另行导出。\n发布检查：真实功能、版权、平台规则、AI 内容声明、本人操作。\n\n本文件由离线 UI 原型生成，不代表任何平台审核结果。`),
 'start-record':()=>{if(!state.checks.every(Boolean))return toast('请先勾选发布前五项检查，再登记已发布');goto('/publish/record/1')},
 'save-record':()=>{if(!state.checks.every(Boolean))return toast('先到发布包逐项完成五项发布前核对');if(!document.getElementById('record-confirm')?.checked)return toast('请先确认你本人已在官方平台手动发布');let u=value('record-url');if(u&&!/^https?:\/\//i.test(u))return toast('作品链接需以 http(s) 开头，或留空');const rec={platform:value('record-platform'),date:value('record-date'),url:u,source:'user_reported'};set({published:[...state.published,rec],confirmSource:false,recordUrl:'',recordDate:rec.date});toast('已保存用户自行登记记录；未经平台验证');goto('/publish')},
 'save-metrics':()=>{let raw=['import-views','import-saves','import-leads'].map(value);if(raw.every(x=>x===''))return toast('请填写至少一项真实指标');if(raw.some(x=>x!==''&&(!/^\d+$/.test(x)||Number(x)<0)))return toast('仅接受非负整数');addMetric({source:'用户手工录入',platform:value('import-platform'),views:raw[0],saves:raw[1],leads:raw[2]})},
 'download-csv':()=>downloadText('叙流_指标导入模板.csv','platform,views,saves,leads\n小红书,120,8,2\n抖音,340,15,3\n','text/csv;charset=utf-8'),
 'read-csv':()=>{let file=document.getElementById('csv-file')?.files?.[0];if(!file)return toast('先选择一个 CSV 文件');const reader=new FileReader();reader.onload=()=>{try{const rows=String(reader.result).replace(/^\uFEFF/,'').trim().split(/\r?\n/).map(s=>s.split(','));const keys=rows.shift().map(s=>s.trim().toLowerCase());if(!['platform','views','saves','leads'].every(k=>keys.includes(k)))return toast('表头应包含 platform,views,saves,leads');const imported=[];for(let row of rows.slice(0,200)){let get=k=>row[keys.indexOf(k)]?.trim()||'';if(!['views','saves','leads'].every(k=>/^\d+$/.test(get(k))))return toast('数据不符合非负整数规则，请检查 CSV');imported.push({platform:get('platform'),source:'用户本地导入 CSV（演示）',views:Number(get('views')),saves:Number(get('saves')),leads:Number(get('leads')),observed_at:new Date().toISOString()})}set({metrics:[...state.metrics,...imported]});toast(`已在此浏览器中读取 ${imported.length} 行演示数据，未上传服务器`)}catch(e){toast('CSV 解析失败，请使用简单逗号分隔模板')}};reader.readAsText(file,'utf-8')},
 'approve-strategy':()=>toast('演示：候选策略已标记同意；无后台自动执行'),
 'decline-strategy':()=>toast('演示：当前策略保持不变'),
 'save-brand':()=>{set({brand:value('brand-name')||state.brand});toast('品牌资料已保存于本地演示状态')},
 'toggle-alerts':()=>set({alerts:!state.alerts}),
 'reset-demo':()=>popup('重置离线演示数据？','<p>将清除这个原型在当前浏览器中保存的模拟发布记录、手动输入的指标和创作者设置。不会影响任何真实平台账号。</p>',`${btn('取消','close-modal','btn')}${btn('确定重置','confirm-reset','btn danger')}`),
 'confirm-reset':()=>{state={...DEFAULT};persist();closePopup();render();toast('已恢复离线原型默认数据')},
 'onboard-brand-next':()=>{if(value('onboard-brand'))set({brand:value('onboard-brand')},false);goto('/onboarding/creator')},
 'onboard-creator-next':()=>{set({creatorName:value('onboard-creator')||state.creatorName,frequency:value('onboard-frequency')||state.frequency},false);goto('/onboarding/preview')},
 'confirm-plan':()=>{set({planSet:true});goto('/dashboard');toast('已确认示例计划；正式日更需要接入后台任务引擎')},
 'close-modal':closePopup
};
document.addEventListener('click',e=>{let btnEl=e.target.closest('[data-action]');if(btnEl){let action=actions[btnEl.dataset.action];if(action){e.preventDefault();action(btnEl)}}else if(e.target.matches('[data-modal-backdrop]'))closePopup();const a=e.target.closest('[data-doc-anchor]');if(a){e.preventDefault();let to=document.getElementById('doc-'+a.dataset.docAnchor);to?.scrollIntoView({behavior:'smooth'})}});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){let c=[...state.checks];c[Number(e.target.dataset.check)]=e.target.checked;set({checks:c})}if(e.target.id==='record-confirm')set({confirmSource:e.target.checked},false);if(e.target.id==='shot-engine'){const engines=[...(state.shotEngines||[])];engines[state.selectedShot]=e.target.value;set({shotEngines:engines});toast('已更新此镜头的制作引擎（仅原型配置）')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePopup();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();actions.search()}});
window.addEventListener('hashchange',()=>{closePopup();render();window.scrollTo(0,0)});
if(!location.hash)history.replaceState(null,'','#/dashboard');render();
